--Q01.Network Throughput
SELECT toUnixTimestamp(toDateTime(toStartOfInterval(toDateTime(common_recv_time),INTERVAL 36 SECOND))) AS stat_time,ROUND(SUM(common_c2s_byte_num)/36) AS bytes_sent_rate,ROUND(SUM(common_s2c_byte_num)/36) AS bytes_received_rate,ROUND(SUM(common_c2s_byte_num + common_s2c_byte_num)/36) AS bytes_rate FROM session_record_cn WHERE common_recv_time >= toUnixTimestamp(@start) AND common_recv_time < toUnixTimestamp(@end) GROUP BY stat_time
--Q02.JSQLParserException(V4.1)
SELECT arrayJoin(splitByChar('_', concat(egress_link_direction, '-egress', '_', ingress_link_direction, '-ingress'))) AS name, SUM(IF(endsWith(name, '-egress'), (IF(client_region IN ('IDC'), common_c2s_byte_num, 0)) + (IF(server_region IN ('IDC'), common_s2c_byte_num, 0)), (IF(client_region IN ('IDC'), common_s2c_byte_num, 0)) + (IF(server_region IN ('IDC'), common_c2s_byte_num, 0)) )) AS bytes, ROUND(AVG(common_establish_latency_ms)) AS establish_latency_ms_avg, ROUND(SUM(common_c2s_tcp_lostlen + common_s2c_tcp_lostlen)/ SUM(common_c2s_byte_num + common_s2c_byte_num + common_c2s_tcp_lostlen + common_s2c_tcp_lostlen), 4) AS tcp_lostlen_percent_avg FROM session_record_cn src WHERE common_recv_time >= toUnixTimestamp(@start) AND common_recv_time < toUnixTimestamp(@end) AND common_l4_protocol IN ('IPv4_TCP', 'IPv6_TCP') GROUP BY name ORDER BY bytes DESC